#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using u64 = unsigned long long;
using u128 = __uint128_t;

u64 mod_pow(u64 a, u64 e, u64 mod) {
    u64 result = 1;
    while (e) {
        if (e & 1) result = (u128)result * a % mod;
        a = (u128)a * a % mod;
        e >>= 1;
    }
    return result;
}

bool is_prime(u64 n) {
    if (n < 2) return false;

    for (u64 p : {2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL, 19ULL,
                  23ULL, 29ULL, 31ULL, 37ULL}) {
        if (n % p == 0) return n == p;
    }

    u64 d = n - 1, s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (u64 a : {2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL,
                  9780504ULL, 1795265022ULL}) {
        if (a % n == 0) continue;

        u64 x = mod_pow(a % n, d, n);
        if (x == 1 || x == n - 1) continue;

        bool composite = true;
        for (u64 r = 1; r < s; ++r) {
            x = (u128)x * x % n;
            if (x == n - 1) {
                composite = false;
                break;
            }
        }

        if (composite) return false;
    }

    return true;
}

u64 largest_prime_not_greater_than(u64 n) {
    if (n == 2) return 2;
    if ((n & 1) == 0) --n;

    while (n >= 3 && !is_prime(n))
        n -= 2;

    return n;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    u64 n;
    cin >> n;

    u64 ans = 0;

    while (n > 0) {
        if (n < 2) {
            ++ans;
            break;
        }

        n -= largest_prime_not_greater_than(n);
        ++ans;
    }

    cout << ans;
    return 0;
}

