#include <bits/stdc++.h>
using namespace std;

const int N = 80000000;
vector<int> primes;

void sieve(int limit) {
    if (limit < 2) return;

    primes.push_back(2);
    vector<bool> composite(limit / 2 + 1);

    for (int i = 3; i <= limit; i += 2) {
        if (composite[i / 2]) continue;
        primes.push_back(i);

        if (1LL * i * i <= limit) {
            for (long long j = 1LL * i * i; j <= limit; j += 2LL * i)
                composite[j / 2] = true;
        }
    }
}

